/**
 * 当前 window.lightAppJssdk 是否已具备活体人脸能力。
 * 注意：仅判断「存在」不够——iOS WKWebView 从 bfcache 恢复（pageshow.persisted=true）
 * 或从第三方页返回时，lightAppJssdk 对象可能残留但原生 JS 桥已被拆除（僵尸态），
 * 此时调用 livenessFaceAuth 会挂起直到超时。僵尸态需整页 reload 重新注入 SDK 才能恢复。
 */
export function isSfbFaceSdkReady() {
  /* #ifdef H5 */
  const sdk = getLightAppJssdk()
  const hasLiveness = typeof sdk?.face?.livenessFaceAuth === 'function'
  const bridge = getAlipayBridgeStatus()
  return hasLiveness && (!isAlipayRuntime() || bridge.hasPostMessage)
  /* #endif */
  /* #ifndef H5 */
  return false
  /* #endif */
}

/** 等待苏服办 JSSDK 异步脚本加载完成 */
export function waitForSfbFaceSdk(timeoutMs = 12000) {
  /* #ifdef H5 */
  return new Promise((resolve, reject) => {
    const startedAt = Date.now()
    const tick = () => {
      const sdk = getLightAppJssdk()
      const hasFaceAuth = typeof sdk?.face?.faceAuth === 'function'
      const hasLiveness = typeof sdk?.face?.livenessFaceAuth === 'function'
      const bridge = getAlipayBridgeStatus()
      const sdkReady = hasLiveness && (!isAlipayRuntime() || bridge.hasPostMessage)

      if (sdkReady) {
        resolve({
          sdk,
          waitedMs: Date.now() - startedAt,
          bridge,
          hasFaceAuth,
          hasLiveness,
        })
        return
      }
      if (Date.now() - startedAt >= timeoutMs) {
        reject(new Error('苏服办 SDK 加载超时，请刷新后重试'))
        return
      }
      setTimeout(tick, 120)
    }
    tick()
  })
  /* #endif */
  /* #ifndef H5 */
  return Promise.resolve({ sdk: null, waitedMs: 0, bridge: {}, hasFaceAuth: false, hasLiveness: false })
  /* #endif */
}

const SFB_FACE_RECOVERY_RELOAD_KEY = 'sfb_face_recovery_reloaded_at'
const SFB_FACE_RECOVERY_RELOAD_WINDOW_MS = 60 * 1000

/**
 * 兜底恢复：当 SDK 处于超时/僵尸态时，整页 reload 一次重新注入原生 SDK。
 * 用 sessionStorage 做一次性闸门，避免 reload 循环（同一分钟内只 reload 一次）。
 * 返回 true 表示已触发 reload（调用方无需再展示失败页）。
 */
export function reloadOnceForSfbFaceRecovery(reason = 'sdk_unavailable') {
  /* #ifdef H5 */
  try {
    const last = Number(sessionStorage.getItem(SFB_FACE_RECOVERY_RELOAD_KEY) || 0)
    if (last && Date.now() - last < SFB_FACE_RECOVERY_RELOAD_WINDOW_MS) {
      // 刚刚已尝试过 reload，仍在失败，说明非僵尸态问题，交给调用方展示失败页
      return false
    }
    sessionStorage.setItem(SFB_FACE_RECOVERY_RELOAD_KEY, String(Date.now()))
    logSfbFace('log', '触发整页刷新以恢复苏服办人脸 SDK', { reason })
    window.location.reload()
    return true
  } catch {
    return false
  }
  /* #endif */
  /* #ifndef H5 */
  return false
  /* #endif */
}

/** 人脸页正常调起成功后清除一次性 reload 闸门，避免影响下一次真实失败时的自动恢复 */
export function clearSfbFaceRecoveryFlag() {
  /* #ifdef H5 */
  try {
    sessionStorage.removeItem(SFB_FACE_RECOVERY_RELOAD_KEY)
  } catch {
    // ignore storage errors
  }
  /* #endif */
}

function showFaceVerifyFail(message, detail = {}) {
  console.error('[苏服办人脸识别][face页面] 展示失败', {
    message,
    ...detail,
    retryCount: verifyRetryCount.value,
    hasSfbToken: !!getSfbToken(),
    userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : '',
  })
  pageStatus.value = 'failed'
  failMessage.value = message || '请确保光线充足、面部清晰后重试'
}

/** SDK 未就绪 / 桥僵尸态导致失败：先尝试整页刷新恢复一次，避免用户面对死循环的「重新识别」 */
function tryRecoverByReload(reason) {
  const reloaded = reloadOnceForSfbFaceRecovery(reason)
  return reloaded
}

function isSdkUnavailableError(errMsg) {
  const msg = `${errMsg || ''}`
  return /SDK 加载超时|SDK 方法不可用|当前环境不支持苏服办人脸识别|SDK 加载失败/i.test(msg)
}

