function retryFaceVerify() {
  if (!canStartVerify.value) return
  // 「重新识别」时若 SDK 处于僵尸态（点了也不会恢复），直接整页刷新重新注入，而不是再次空等超时
  if (!isSfbFaceSdkReady() && tryRecoverByReload('retry_button')) {
    return
  }
  verifyRetryCount.value = 0
  pageStatus.value = 'verifying'
  failMessage.value = '请确保光线充足、面部清晰后重试'
  startFaceVerify()
}

function handleBfcachePageShow(event) {
  /* #ifdef H5 */
  // iOS WKWebView 从 bfcache 恢复：原生 JS 桥已被拆除，lightAppJssdk 残留为僵尸态
  if (!event?.persisted) return
  console.warn('[苏服办人脸识别][face页面] 检测到 bfcache 恢复（persisted）', {
    sdkReady: isSfbFaceSdkReady(),
  })
  if (canStartVerify.value && !isSfbFaceSdkReady() && !isSfbFacePending()) {
    tryRecoverByReload('bfcache_pageshow')
  }
  /* #endif */
}

onLoad((options) => {
