    location ^~ /v3.0/ {
        proxy_pass http://unlimited.g.h5.admin.web.v2.benefit.shiqu.wuxi.test.zhi.com/api/v3.0/;
    }

    location / {
        try_files $uri $uri/ /index.html;
    }
}

